package dev.discraft.forge.server;

import dev.discraft.forge.bridge.*;
import com.google.gson.*;
import net.minecraft.ChatFormatting;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.item.enchantment.Enchantments;
import java.nio.file.*;
import java.util.*;

/** Actual headless ItemStack semantics and production multipart adapter against loopback only. */
final class ItemTooltipAcceptance {
    private static final List<String> checks=new ArrayList<>();
    private static void check(boolean value,String text){if(!value)throw new AssertionError(text);checks.add("PASS "+text);}
    private static ItemSnapshot snapshot(ServerPlayer player,ItemStack stack,ComponentText text){player.setItemInHand(InteractionHand.MAIN_HAND,stack);return ItemSnapshot.capture(player,text);}
    private static String plain(ItemSnapshot item){return item.tooltip().lines().stream().map(ItemTooltip.Line::plain).reduce("",(a,b)->a+"\n"+b);}
    private static void nativeOracle(ServerPlayer player,ItemStack original,ItemSnapshot captured){
        var lines=original.getTooltipLines(player,TooltipFlag.Default.ADVANCED);int tail=original.hasTag()?2:1;var expected=lines.subList(0,lines.size()-tail).stream().map(Component::getString).toList();
        check(captured.tooltip().lines().stream().map(ItemTooltip.Line::plain).toList().equals(expected),"Pinned 1.20.1 allowed native tooltip lines match: "+original.getItem());
    }
    static void run(ServerPlayer player,Path output,ResourcePackIndex resources,boolean vanilla)throws Exception{
        checks.clear();translationOnGameThread(player,output);var en=new ComponentText(ResourcePackIndex.empty(),"en_us");var zh=new ComponentText(resources,"zh_tw");var renderer=new HeadlessItemRenderer(resources);var metadata=new JsonArray();
        var sword=new ItemStack(Items.DIAMOND_SWORD);var normal=snapshot(player,sword,en);nativeOracle(player,sword,normal);check(plain(normal).contains("7 Attack Damage")&&plain(normal).contains("1.6 Attack Speed")&&!plain(normal).contains("Durability"),"Fresh sword keeps exact base attribute numbers and omits undamaged advanced durability");
        var tool=new ItemStack(Items.NETHERITE_PICKAXE);tool.enchant(Enchantments.BLOCK_EFFICIENCY,5);tool.enchant(Enchantments.MENDING,1);tool.enchant(Enchantments.SILK_TOUCH,1);tool.enchant(Enchantments.UNBREAKING,3);tool.setDamageValue(100);tool.getOrCreateTag().putInt("HideFlags",2);
        var enchanted=snapshot(player,tool,en);nativeOracle(player,tool,enchanted);String content=plain(enchanted);check(content.contains("Efficiency V")&&content.contains("Mending")&&content.contains("Silk Touch")&&content.contains("Unbreaking III")&&content.contains("1931 / 2031")&&!content.contains("Attack"),"Reference-like enchantments, actual durability and HideFlags are derived from the real tool");
        check(enchanted.tooltip().lines().get(0).runs().get(0).color()==ChatFormatting.AQUA.getColor(),"Actual enchanted rarity colors the title, not a fixed example color");
        card("tooltip-enchanted-tool",enchanted,renderer,output,metadata,vanilla);
        var named=new ItemStack(Items.DIAMOND_SWORD);named.setHoverName(Component.literal("星光劍").withStyle(ChatFormatting.GOLD,ChatFormatting.BOLD));named.enchant(Enchantments.SHARPNESS,3);named.setDamageValue(7);var lore=new ListTag();lore.add(StringTag.valueOf(Component.Serializer.toJson(Component.literal("來自伺服器的物品說明").withStyle(ChatFormatting.BLUE))));named.getOrCreateTagElement("display").put("Lore",lore);named.getOrCreateTag().putString("pages","private-book-body-must-not-leak");named.getOrCreateTag().putString("BlockEntityTag","private-container-must-not-leak");
        var custom=snapshot(player,named,zh);check(plain(custom).contains("星光劍")&&plain(custom).contains("來自伺服器")&&!plain(custom).contains("private-"),"Custom Traditional Chinese name/lore survives with no book/container fields");
        check(custom.tooltip().lines().get(0).runs().get(0).color()==ChatFormatting.GOLD.getColor()&&custom.tooltip().lines().get(0).runs().get(0).bold()&&custom.tooltip().lines().get(0).runs().get(0).italic(),"Custom name preserves gold/bold and vanilla custom-name italic style");
        card("tooltip-traditional-chinese",custom,renderer,output,metadata,vanilla);
        var emptyOverride=new ItemStack(Items.DIAMOND_SWORD);emptyOverride.getOrCreateTag().put("AttributeModifiers",new ListTag());var empty=snapshot(player,emptyOverride,en);nativeOracle(player,emptyOverride,empty);check(empty.tooltip().lines().size()==1&&!plain(empty).contains("Attack"),"Explicit empty attribute override never restores default damage/speed in the Discord image");
        var attack=player.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE);double previousBase=attack.getBaseValue();
        try{attack.setBaseValue(17);for(boolean enchant:List.of(false,true)){
            var override=new ItemStack(Items.DIAMOND_SWORD);var modifiers=new ListTag();var modifier=new CompoundTag();modifier.putString("AttributeName","minecraft:generic.attack_damage");modifier.putString("Name","pinned native UUID oracle");modifier.putDouble("Amount",6);modifier.putInt("Operation",0);modifier.putUUID("UUID",UUID.fromString("cb3f55d3-645c-4f38-a497-9c13a33db5cf"));modifier.putString("Slot","mainhand");modifiers.add(modifier);override.getOrCreateTag().put("AttributeModifiers",modifiers);if(enchant)override.enchant(Enchantments.SHARPNESS,3);
            var captured=snapshot(player,override,en);nativeOracle(player,override,captured);check(plain(captured).contains("+6 Attack Damage")&&!plain(captured).contains("23 Attack Damage")&&!plain(captured).contains("25 Attack Damage"),"Pinned explicit NBT vanilla UUID does not gain player base/enchant totals, player base=17, enchanted="+enchant);
            var defaults=new ItemStack(Items.DIAMOND_SWORD);if(enchant)defaults.enchant(Enchantments.SHARPNESS,3);var defaultSnapshot=snapshot(player,defaults,en);nativeOracle(player,defaults,defaultSnapshot);check(plain(defaultSnapshot).contains((enchant?"25":"23")+" Attack Damage"),"Pinned default UUID adds authoritative player base and allowed enchant bonus, enchanted="+enchant);
        }}finally{attack.setBaseValue(previousBase);}
        var filtered=new ItemStack(Items.DIAMOND_SWORD);var entries=new ListTag();var entry=new CompoundTag();entry.putString("AttributeName","minecraft:generic.attack_damage");entry.putString("Name","fixture");entry.putDouble("Amount",5);entry.putInt("Operation",0);entry.putUUID("UUID",new UUID(1,2));entry.putString("Slot","invalid-slot");entries.add(entry);filtered.getOrCreateTag().put("AttributeModifiers",entries);check(snapshot(player,filtered,en).tooltip().lines().size()==1,"Filtered-empty attribute override remains empty");
        var hidden=tool.copy();hidden.getOrCreateTag().putBoolean("Unbreakable",true);hidden.getOrCreateTag().putInt("HideFlags",7);check(snapshot(player,hidden,en).tooltip().lines().size()==1,"HideFlags suppresses enchants, modifiers and unbreakable while native isDamaged suppresses durability");
        hidden.getOrCreateTag().putInt("HideFlags",3);check(plain(snapshot(player,hidden,en)).contains("Unbreakable"),"Visible unbreakable line uses native rules");
        var hand=snapshot(player,ItemStack.EMPTY,en);check(hand.empty()&&ItemExpansion.expand(RelayRecord.draft(UUID.randomUUID(),"%item",null),hand,renderer).discord().attachments().isEmpty(),"Empty hand generates no tooltip attachment");
        var longStack=new ItemStack(Items.DIAMOND_SWORD);var longLore=new ListTag();for(int i=0;i<3;i++)longLore.add(StringTag.valueOf(Component.Serializer.toJson(Component.literal("Long text 中文 ".repeat(12)+"123456.75"))));longStack.getOrCreateTagElement("display").put("Lore",longLore);var lengthy=snapshot(player,longStack,zh);var longImage=renderer.tooltip(lengthy);check(longImage.width()<=768&&longImage.height()>renderer.tooltip(normal).height()&&plain(lengthy).contains("123456.75"),"Long multilingual content wraps by measured glyphs without dropping attribute-like numbers");
        var excessive=new ArrayList<ItemTooltip.Line>();for(int i=0;i<64;i++)excessive.add(ItemTooltip.nameOnly("X".repeat(120),"minecraft:default").lines().get(0));try{new ItemTooltipRenderer(resources).render(new ItemTooltip(excessive));throw new AssertionError("Too tall tooltip accepted");}catch(IllegalArgumentException expected){check(true,"Excess content explicitly rejects before PNG rather than silently truncating");}
        var translated=Component.translatableWithFallback("discraft.test.styled","%2$s / %1$s / %%",Component.literal("中文").withStyle(ChatFormatting.GOLD),Component.literal("English").withStyle(ChatFormatting.BLUE));var line=zh.tooltipLine(translated);check(line.plain().equals("English / 中文 / %")&&line.runs().stream().anyMatch(r->r.text().equals("中文")&&r.color()==ChatFormatting.GOLD.getColor()),"Numbered translation parameters retain nested styles and literal percent");
        var unknown=ItemTooltip.nameOnly("Unknown glyph "+new String(Character.toChars(0x10ffff)),"minecraft:default");var unknownImage=new ItemTooltipRenderer(resources).render(unknown);check(unknownImage.fontFallback()&&unknownImage.missingGlyphs().contains("U+10FFFF"),"Actual missing glyphs retain their visible codepoint notice and diagnostic metadata");
        Files.writeString(output.resolve("tooltip-metadata.json"),metadata.toString());checks.add("PASS "+checks.size()+" real ItemStack tooltip/multipart checks; loopback only, vanilla language resources="+vanilla);Files.write(output.resolve("tooltip-result.txt"),checks);System.out.println(checks.get(checks.size()-1));
    }
    private static void translationOnGameThread(ServerPlayer player,Path output)throws Exception{
        Path directory=output.resolve("item-fixture-packs");Files.createDirectories(directory);var language=new JsonObject();language.addProperty("budget.outer","%1$s".repeat(500));language.addProperty("budget.inner","%%".repeat(4096));
        try(var zip=new java.util.zip.ZipOutputStream(Files.newOutputStream(directory.resolve("bounded-translations.zip")))){for(var entry:Map.of("pack.mcmeta","{\"pack\":{\"pack_format\":15,\"description\":\"Local safe translation expansion fixture\"}}","assets/minecraft/lang/en_us.json",language.toString()).entrySet()){zip.putNextEntry(new java.util.zip.ZipEntry(entry.getKey()));zip.write(entry.getValue().getBytes(java.nio.charset.StandardCharsets.UTF_8));zip.closeEntry();}}
        var resources=ResourcePackIndex.load(directory,List.of("bounded-translations.zip"));var stack=new ItemStack(Items.DIAMOND_SWORD);String json=Component.Serializer.toJson(Component.translatable("budget.outer",Component.translatable("budget.inner")));if(json.length()>512)throw new AssertionError("Explosive lore fixture exceeds actual allowlist input limit");var lore=new ListTag();lore.add(StringTag.valueOf(json));stack.getOrCreateTagElement("display").put("Lore",lore);
        try{snapshot(player,stack,new ComponentText(resources,"en_us"));throw new AssertionError("Game-thread translation multiplication accepted");}catch(IllegalArgumentException expected){check(expected.getMessage().contains("generated node budget")&&player.server.isSameThread(),"Actual <=512-character authoritative lore rejects repeated translation expansion on the game thread before oversized tree generation");}
    }
    private static void card(String name,ItemSnapshot snapshot,HeadlessItemRenderer renderer,Path output,JsonArray metadata,boolean vanilla)throws Exception{
        var image=renderer.tooltip(snapshot);check(image.height()==24+snapshot.tooltip().lines().size()*24&&image.missingGlyphs().isEmpty(),"Fallback font contributes no diagnostic footer row to the actual item PNG: "+name);var record=new RelayRecord(UUID.randomUUID(),"Aitchn","看看我的 %item",List.of(),Map.of(),Map.of());var expanded=ItemExpansion.expand(record,snapshot,renderer).discord();var payload=ItemFixtures.sendToLocalDiscord(expanded);
        check(expanded.attachments().size()==1&&Arrays.equals(expanded.attachments().get(0).bytes(),image.attachment().bytes())&&payload.getAsJsonObject("allowed_mentions").getAsJsonArray("parse").isEmpty()&&payload.getAsJsonObject("allowed_mentions").getAsJsonArray("users").isEmpty()&&!payload.toString().contains("private-"),"Real authoritative snapshot reaches official adapter multipart only on loopback: "+name);
        Files.write(output.resolve(name+".png"),image.attachment().bytes());var item=new JsonObject();item.addProperty("file",name+".png");item.addProperty("width",image.width());item.addProperty("height",image.height());item.addProperty("bytes",image.attachment().bytes().length);item.addProperty("font_fallback",image.fontFallback());item.addProperty("cached_vanilla_language",vanilla);item.addProperty("raw_body",payload.get("content").getAsString());var lines=new JsonArray();snapshot.tooltip().lines().forEach(l->lines.add(l.plain()));item.add("semantic_lines",lines);metadata.add(item);
    }
}
